package com.gestordevendas.api.food; import java.math.BigDecimal; import java.util.*; public record SnackResponse(UUID id, String name, BigDecimal price, List<String> ingredients, List<Additional> additionals){public record Additional(String name, BigDecimal price){} static SnackResponse from(Snack s){return new SnackResponse(s.getId(),s.getName(),s.getPrice(),List.copyOf(s.getIngredients()),s.getAdditionals().stream().map(a->new Additional(a.getName(),a.getPrice())).toList());}}